 namespace Pterodactyl\Services\Dezerx\DiscordBot; class Ui { public const V2 = 32768; public const EPHEMERAL = 64; public const MAX_COMPONENTS = 40; public const MAX_TEXT = 4000; public const PRIMARY = 1; public const SECONDARY = 2; public const SUCCESS = 3; public const DANGER = 4; public const LINK = 5; public const RUNNING = 0x22C55E; public const PENDING = 0xF59E0B; public const OFFLINE = 0xEF4444; public const MUTED = 0x64748B; public static function message(array $components, array $roles = [], bool $everyone = false): array { return [ 'components' => array_values(array_filter($components)), 'allowed_mentions' => ['parse' => $everyone ? ['everyone'] : [], 'roles' => array_values($roles)], ]; } public static function container(array $components, ?int $accent = null): array { return array_filter([ 'type' => 17, 'accent_color' => $accent, 'components' => array_values(array_filter($components)), ], fn ($value) => $value !== null); } public static function text(string $content): array { return ['type' => 10, 'content' => self::clip($content, self::MAX_TEXT)]; } public static function section(array|string $texts, ?array $accessory): array { $texts = array_slice(array_values(array_filter((array) $texts, fn ($text) => $text !== null && $text !== '')), 0, 3); if ($accessory === null) { return self::text(implode("\n", $texts)); } return [ 'type' => 9, 'components' => array_map(fn (string $text) => self::text($text), $texts === [] ? ["\u{200b}"] : $texts), 'accessory' => $accessory, ]; } public static function thumbnail(?string $url, ?string $description = null): ?array { if ($url === null || $url === '') { return null; } return array_filter([ 'type' => 11, 'media' => ['url' => Art::forDiscord($url)], 'description' => $description === null ? null : self::clip($description, 1024), ], fn ($value) => $value !== null); } public static function gallery(array $urls): ?array { $items = array_values(array_map( fn (string $url) => ['media' => ['url' => Art::forDiscord($url)]], array_slice(array_values(array_filter($urls)), 0, 10), )); return $items === [] ? null : ['type' => 12, 'items' => $items]; } public static function divider(bool $line = true, bool $large = false): array { return ['type' => 14, 'divider' => $line, 'spacing' => $large ? 2 : 1]; } public static function row(array $components): ?array { $components = array_values(array_filter($components)); return $components === [] ? null : ['type' => 1, 'components' => array_slice($components, 0, 5)]; } public static function button(string $id, string $label, int $style = self::SECONDARY, bool $disabled = false): array { return array_filter([ 'type' => 2, 'style' => $style, 'custom_id' => substr($id, 0, 100), 'label' => self::clip($label, 80), 'disabled' => $disabled ?: null, ], fn ($value) => $value !== null); } public static function link(?string $url, string $label): ?array { if ($url === null || $url === '' || preg_match('#^https?://#i', $url) !== 1) { return null; } return array_filter([ 'type' => 2, 'style' => self::LINK, 'url' => mb_substr($url, 0, 512), 'label' => self::clip($label, 80), ], fn ($value) => $value !== null); } public static function select(string $id, string $placeholder, array $options, bool $disabled = false): ?array { $options = array_slice(array_values(array_filter($options)), 0, 25); if ($options === []) { return null; } return array_filter([ 'type' => 3, 'custom_id' => substr($id, 0, 100), 'placeholder' => self::clip($placeholder, 150), 'options' => $options, 'min_values' => 1, 'max_values' => 1, 'disabled' => $disabled ?: null, ], fn ($value) => $value !== null); } public static function option(string $value, string $label, ?string $description = null, bool $default = false): array { return array_filter([ 'value' => substr($value, 0, 100), 'label' => self::clip($label === '' ? $value : $label, 100), 'description' => $description === null || $description === '' ? null : self::clip($description, 100), 'default' => $default ?: null, ], fn ($value) => $value !== null); } public static function modal(string $id, string $title, array $inputs): array { return [ 'custom_id' => substr($id, 0, 100), 'title' => self::clip($title, 45), 'components' => array_map(fn (array $input) => ['type' => 1, 'components' => [$input]], array_slice($inputs, 0, 5)), ]; } public static function input(string $id, string $label, bool $paragraph = false, bool $required = true, int $max = 200, ?string $placeholder = null, ?string $value = null): array { return array_filter([ 'type' => 4, 'custom_id' => substr($id, 0, 100), 'label' => self::clip($label, 45), 'style' => $paragraph ? 2 : 1, 'required' => $required, 'max_length' => max(1, min(4000, $max)), 'placeholder' => $placeholder === null ? null : self::clip($placeholder, 100), 'value' => $value, ], fn ($value) => $value !== null); } public static function count(array $components): int { $total = 0; foreach ($components as $component) { if (!is_array($component) || !isset($component['type'])) { continue; } ++$total; if (isset($component['components']) && is_array($component['components'])) { $total += self::count($component['components']); } if (isset($component['accessory']) && is_array($component['accessory'])) { $total += self::count([$component['accessory']]); } } return $total; } public static function textLength(array $components): int { $total = 0; foreach ($components as $component) { if (!is_array($component)) { continue; } if (($component['type'] ?? null) === 10) { $total += mb_strlen((string) ($component['content'] ?? '')); } if (isset($component['components']) && is_array($component['components'])) { $total += self::textLength($component['components']); } } return $total; } public static function clip(string $value, int $max): string { return mb_strlen($value) <= $max ? $value : rtrim(mb_substr($value, 0, max(1, $max - 1))) . '…'; } } 